HOURGLASS_ENV=test python3 -m unittest tests.test_timesheet -v 2>&1 | tail -4; echo "--- full suite"; make check 2>&1 | tail -3; echo "--- lint"; make lint 2>&1 | tail -1; echo "--- line lengths, blank runs, function sizes"; awk 'length > 60 {print FILENAME": "FNR": "length}' hourglass/timesheet.py tests/test_timesheet.py; awk 'prev=="" && $0=="" {print FILENAME": double blank at "FNR} {prev=$0}' hourglass/timesheet.py tests/test_timesheet.py; python3 -c "
import ast,sys
for path in ['hourglass/timesheet.py','tests/test_timesheet.py']:
    tree=ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node,(ast.FunctionDef,)):
            n=node.end_lineno-node.lineno+1
            if n>8: print(path,node.name,n)
            for sub in ast.walk(node):
                if isinstance(sub,ast.Name) and isinstance(sub.ctx,ast.Store) and len(sub.id)<4: print(path,'short name',sub.id)
print('size check done')
"; echo "--- full stop check"; git status --short

